package app.fluxa

import android.content.Context
import android.widget.TextView
import android.widget.Toast

/**
 * Runtime translation. The UI text in the code base is written in Thai; every string that passes
 * through [TrTextView], [toastMake] or [tr] is looked up here and swapped for the language chosen in
 * Settings (0 = Thai, 1 = English, 2 = Chinese, 3 = Spanish, 4 = Japanese, 5 = Korean). Unknown strings stay as they are.
 */
object I18n {
    /** Language names, always shown in their own language. */
    val LANG_NAMES = listOf("ไทย", "English", "中文", "Español", "日本語", "한국어")

    private class Entry(val th: String, val tr: Array<String>)

    private fun e(th: String, en: String, zh: String, es: String, ja: String, ko: String) =
        Entry(th, arrayOf(en, zh, es, ja, ko))

    private val exact: Map<String, Entry> by lazy { EXACT.associateBy { it.th } }
    /** Fragments for strings that carry a dynamic tail, longest first. */
    private val frags: List<Entry> by lazy { FRAGS.sortedByDescending { it.th.length } }
    private val cache = Array(LANG_NAMES.size - 1) { java.util.concurrent.ConcurrentHashMap<String, String>() }

    private fun hasThai(s: CharSequence): Boolean {
        for (ch in s) if (ch in '\u0E00'..'\u0E7F') return true
        return false
    }

    /** Translates [s] into the current language (Thai text is returned unchanged for Thai). */
    fun tr(s: String): String {
        val l = AppSettings.lang
        if (l <= 0 || s.isEmpty() || !hasThai(s)) return s
        val c = cache[l - 1]
        return c.getOrPut(s) { translate(s, l - 1) }
    }

    /** Translates a template that contains {0}, {1}… placeholders, then fills them in. */
    fun f(template: String, vararg args: Any?): String {
        var out = tr(template)
        args.forEachIndexed { i, a -> out = out.replace("{" + i + "}", a.toString()) }
        return out
    }

    fun tr(ctx: Context, s: String): String {
        AppSettings.load(ctx)
        return tr(s)
    }

    fun toastMake(ctx: Context, text: CharSequence, duration: Int): Toast {
        AppSettings.load(ctx)
        return Toast.makeText(ctx, tr(text.toString()), duration)
    }

    private fun translate(s: String, li: Int): String {
        exact[s]?.let { return it.tr[li] }
        if (s.contains('\n')) return s.split('\n').joinToString("\n") { translate(it, li) }
        val core = s.trim()
        if (core.isEmpty()) return s
        if (core != s) {
            val lead = s.substring(0, s.indexOf(core))
            val trail = s.substring(lead.length + core.length)
            return lead + translate(core, li) + trail
        }
        exact[core]?.let { return it.tr[li] }
        if (core.contains(" · ")) return core.split(" · ").joinToString(" · ") { translate(it, li) }
        var out = core
        for (f in frags) if (out.contains(f.th)) out = out.replace(f.th, f.tr[li])
        return out
    }

