/** TextView that translates any Thai text it is given (setText covers `.text =` too). */
open class TrTextView(context: Context) : TextView(context) {
    override fun setText(text: CharSequence?, type: BufferType?) {
        val t = if (text is String) I18n.tr(text) else text
        val icons = Glyphs.has(t)
        super.setText(if (icons) Glyphs.apply(context, t) else t, if (icons) BufferType.SPANNABLE else type)
    }
}
